def shapes(rows):
 pts=[(x,y) for y,row in enumerate(rows) for x,c in enumerate(row) if c=='b']
 if not pts:return []
 # group by gaps x/y connected components with 8-neighbor
 rem=set(pts); comps=[]
 while rem:
  st=[rem.pop()]; comp=[]
